    <main class="page-shell">
      <section class="support-layout" aria-label="Support contact">
        <div class="support-intro">
          <div class="eyebrow">Support</div>
          <h1>Contact our support team.</h1>
          <p>
            Tell us what you need and we will route your request to the right person. Share your name and email
            so we can follow up, and add a phone number if you want a call back.
          </p>
        </div>

        <div class="contact-card">
          <h2>Send a message</h2>
          <p>We usually respond within one business day.</p>

          <form id="support-form" novalidate>
            <div class="form-field">
              <label for="full-name">Full name</label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                placeholder="Jordan Lee"
                required
                aria-describedby="full-name-error"
              />
              <p class="error-text" id="full-name-error" hidden>Please enter your full name.</p>
            </div>

            <div class="form-field">
              <label for="email-address">Email address</label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                placeholder="jordan@example.com"
                required
                aria-describedby="email-address-error"
              />
              <p class="error-text" id="email-address-error" hidden>Please enter a valid email address.</p>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number</label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                inputmode="tel"
                placeholder="(555) 123-4567"
                aria-describedby="phone-number-help phone-number-error"
              />
              <p class="helper-text" id="phone-number-help">
                Optional. Use digits only or include spaces, dashes, or parentheses, for example (555) 123-4567.
              </p>
              <p class="error-text" id="phone-number-error" hidden>
                Enter a valid phone number using digits, spaces, dashes, parentheses, or an optional leading plus sign.
              </p>
            </div>

            <button type="submit">Submit request</button>
            <p class="status-message" id="form-status" aria-live="polite"></p>
          </form>
        </div>
      </section>
    </main>

    <script>
      const form = document.querySelector("#support-form");
      const statusMessage = document.querySelector("#form-status");

      const fields = {
        fullName: {
          input: document.querySelector("#full-name"),
          error: document.querySelector("#full-name-error"),
          validate(value) {
            return value.trim().length > 0 ? "" : "Please enter your full name.";
          }
        },
        email: {
          input: document.querySelector("#email-address"),
          error: document.querySelector("#email-address-error"),
          validate(value) {
            if (!value.trim()) {
              return "Please enter your email address.";
            }

            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
              ? ""
              : "Please enter a valid email address.";
          }
        },
        phone: {
          input: document.querySelector("#phone-number"),
          error: document.querySelector("#phone-number-error"),
          validate(value) {
            if (!value.trim()) {
              return "";
            }

            return /^[+]?[0-9()\-\s]{7,20}$/.test(value)
              ? ""
              : "Enter a valid phone number using digits, spaces, dashes, parentheses, or an optional leading plus sign.";
          }
        }
      };

      const showFieldState = (fieldConfig, message) => {
        fieldConfig.error.textContent = message;
        fieldConfig.error.hidden = !message;
        fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
      };

      Object.values(fields).forEach((fieldConfig) => {
        fieldConfig.input.addEventListener("blur", () => {
          const message = fieldConfig.validate(fieldConfig.input.value);
          showFieldState(fieldConfig, message);
        });

        fieldConfig.input.addEventListener("input", () => {
          if (!fieldConfig.error.hidden) {
            const message = fieldConfig.validate(fieldConfig.input.value);
            showFieldState(fieldConfig, message);
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        let hasErrors = false;

        Object.values(fields).forEach((fieldConfig) => {
          const message = fieldConfig.validate(fieldConfig.input.value);
          showFieldState(fieldConfig, message);

          if (message && !hasErrors) {
            hasErrors = true;
            fieldConfig.input.focus();
          }
        });

        statusMessage.textContent = hasErrors ? "" : "Thanks. Your support request is ready to be sent.";

        if (!hasErrors) {
          form.reset();
          Object.values(fields).forEach((fieldConfig) => {
            showFieldState(fieldConfig, "");
          });
        }
      });
    </script>
  </body>
